-- Seed SAP country and region F4 master data for self-hosted deployments.
-- Generated from the Lovable Cloud cache. Safe to re-run.

GRANT SELECT, INSERT, UPDATE, DELETE ON public.sap_master_data TO authenticated;
GRANT ALL ON public.sap_master_data TO service_role;

ON CONFLICT (master_type, code) DO UPDATE SET
  description = EXCLUDED.description,
  extra = EXCLUDED.extra,
  source = EXCLUDED.source,
  last_synced_at = EXCLUDED.last_synced_at,
  updated_at = now();

NOTIFY pgrst, 'reload schema';
